// Bridge that brings in the `pyo3_libpython_link!` macro definition generated by
// the build system for the auto-detected Python shared library.
//
// With cargo, the build script writes the generated macro into `OUT_DIR`.
//
// With meson, the crate is mirrored into the build directory (via
// `structured_sources` in `meson.build`) and the generated file is placed
// next to this file, so a plain relative include works.
#[cfg(pyo3_meson_build)]
include!("pyo3_libpython_link.rs");

#[cfg(not(pyo3_meson_build))]
include!(concat!(env!("OUT_DIR"), "/pyo3_libpython_link.rs"));
